import numpy as np


class RefinedCoordMomentumES:
    """
    Mixed-variable IPOP-style (mu+lambda) ES with a 0,1,2,1 stage schedule:
      0) global ES from stratified LHS (population doubles every global run),
      1) per-coordinate pattern search on the incumbent with multi-scale momentum
         extrapolation (1x, 2x, 4x of the accumulated success direction),
         per-coordinate step doubling on success and shrinking on failure,
      2) local ES restarts around the incumbent with a 1/5-type radius adaptation.
    A global cache makes repeated points free and every batch is budget-capped.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        d = self.dim
        budget = self.budget
        rng = np.random.default_rng()

        lb = np.asarray(func.bounds.lb, dtype=float).reshape(-1)
        ub = np.asarray(func.bounds.ub, dtype=float).reshape(-1)
        types = list(func.variable_types)
        n_values = getattr(func, "n_values", None)

        is_cont = np.array([t == "continuous" for t in types], dtype=bool)
        is_ord = np.array([t == "ordinal" for t in types], dtype=bool)
        cont = np.where(is_cont)[0]
        disc = np.where(~is_cont)[0]
        nc = len(cont)

        nv = np.ones(d, dtype=int)
        for i in disc:
            nv[i] = int(n_values[i]) if n_values is not None else 2
        span = np.where(is_cont, ub - lb, 1.0)

        tau = 1.0 / np.sqrt(2.0 * np.sqrt(max(1, nc)))
        lam0 = max(12, 4 * d)
        mu0 = max(4, lam0 // 3)

        used = 0
        cache = {}
        best = {"y": np.inf, "x": None}
        local_mult = {"s": 1.0}

        def repair(X):
            X = np.array(X, dtype=float, copy=True)
            if nc:
                X[:, cont] = np.clip(X[:, cont], lb[cont], ub[cont])
            if len(disc):
                X[:, disc] = np.clip(np.rint(X[:, disc]), 0, nv[disc] - 1)
            return X

        def evaluate(X):
            nonlocal used
            X = repair(np.atleast_2d(X))
            n = len(X)
            keys = [x.tobytes() for x in X]
            ys = np.full(n, np.inf)
            new, seen_new = [], set()
            for i, k in enumerate(keys):
                if k in cache:
                    ys[i] = cache[k]
                elif k not in seen_new:
                    seen_new.add(k)
                    new.append(i)
            rem = budget - used
            if new and rem <= 0:
                return None
            sel = new[:rem]
            if sel:
                Y = np.asarray(func(X[sel]), dtype=float).reshape(-1)
                Y = np.nan_to_num(Y, nan=np.inf)
                used += len(sel)
                for j, i in enumerate(sel):
                    cache[keys[i]] = float(Y[j])
                    if Y[j] < best["y"]:
                        best["y"] = float(Y[j])
                        best["x"] = X[i].copy()
            for i, k in enumerate(keys):
                if k in cache:
                    ys[i] = cache[k]
            return X, ys

        def lhs(n):
            X = np.empty((n, d), dtype=float)
            for j in range(d):
                u = (rng.permutation(n) + rng.random(n)) / n
                if is_cont[j]:
                    X[:, j] = lb[j] + u * (ub[j] - lb[j])
                else:
                    X[:, j] = np.minimum(np.floor(u * nv[j]), nv[j] - 1)
            return repair(X)

        def mutate_discrete(c, pm):
            for j in disc:
                if nv[j] > 1 and rng.random() < pm:
                    k = nv[j]
                    cur = int(round(c[j]))
                    if is_ord[j] and rng.random() < 0.7:
                        s = 1 if rng.random() < 0.5 else -1
                        nxt = cur + s
                        if nxt < 0 or nxt > k - 1:
                            nxt = cur - s
                        c[j] = nxt
                    else:
                        r = int(rng.integers(0, k - 1))
                        if r >= cur:
                            r += 1
                        c[j] = r
            return c

        def make_child(P, S):
            mu = len(P)
            a, b = rng.integers(0, mu, size=2)
            i1, i2 = min(a, b), b
            p1, p2 = P[i1], P[i2]
            s = np.sqrt(S[i1] * S[i2]) * np.exp(tau * rng.standard_normal())
            s = float(np.clip(s, 1e-3, 0.5))
            m = rng.random(d) < 0.5
            c = np.where(m, p1, p2).astype(float)
            if nc:
                if rng.random() < 0.5:
                    c[cont] = 0.5 * (p1[cont] + p2[cont])
                rate = rng.uniform(1.0 / nc, 1.0)
                mask = rng.random(nc) < rate
                if not mask.any():
                    mask[rng.integers(nc)] = True
                c[cont] = c[cont] + mask * rng.standard_normal(nc) * s * span[cont]
            if len(disc):
                pm = rng.uniform(1.0 / d, 3.0 / d)
                c = mutate_discrete(c, pm)
            return c, s

        def breed(P, S, n):
            children, sigs, keys = [], [], set()
            tries = 0
            while len(children) < n and tries < 30 * n:
                tries += 1
                c, s = make_child(P, S)
                c = repair(c[None, :])[0]
                k = c.tobytes()
                if k in cache or k in keys:
                    continue
                keys.add(k)
                children.append(c)
                sigs.append(s)
            while len(children) < n:
                c, s = make_child(P, S)
                children.append(repair(c[None, :])[0])
                sigs.append(s)
            return np.array(children), np.array(sigs)

        def es_run(X0, mu, lam, s_init, patience):
            res = evaluate(X0)
            if res is None:
                return False
            X0, y0 = res
            order = np.argsort(y0)[:mu]
            P, Py = X0[order], y0[order]
            Ps = np.full(len(P), s_init)
            gen_best = Py[0]
            start_best = best["y"]
            stagn = 0
            while used < budget and stagn < patience:
                n_child = min(lam, budget - used)
                if n_child <= 0:
                    break
                C, Cs = breed(P, Ps, n_child)
                res = evaluate(C)
                if res is None:
                    break
                Cx, Cy = res
                allX = np.vstack([P, Cx])
                allY = np.concatenate([Py, Cy])
                allS = np.concatenate([Ps, Cs[:len(Cx)]])
                order = np.argsort(allY, kind="stable")[:mu]
                P, Py, Ps = allX[order], allY[order], allS[order]
                if Py[0] < gen_best - 1e-12 * (1.0 + abs(gen_best)):
                    gen_best = Py[0]
                    stagn = 0
                else:
                    stagn += 1
            return best["y"] < start_best - 1e-12 * (1.0 + abs(start_best))

        def coord_polish(x0, y0, max_evals):
            # Per-coordinate pattern search with multi-scale momentum extrapolation.
            x, y = x0.copy(), float(y0)
            cs = np.full(d, 0.1)
            mom = np.zeros(d)  # accumulated success direction (in x units)
            spent = 0
            while spent < max_evals and used < budget:
                cands, meta = [], []
                for k in cont:
                    for sgn in (1.0, -1.0):
                        c = x.copy()
                        c[k] = x[k] + sgn * cs[k] * span[k]
                        cands.append(c)
                        meta.append(("c", k))
                if nc and np.any(mom[cont] != 0.0):
                    for scale in (1.0, 2.0, 4.0):
                        c = x.copy()
                        c[cont] = x[cont] + scale * mom[cont]
                        cands.append(c)
                        meta.append(("m", -1))
                for j in disc:
                    if nv[j] <= 1:
                        continue
                    cur = int(round(x[j]))
                    vals = [v for v in range(nv[j]) if v != cur]
                    if len(vals) > 4:
                        vals = list(rng.choice(vals, 4, replace=False))
                    for v in vals:
                        c = x.copy()
                        c[j] = v
                        cands.append(c)
                        meta.append(("d", j))
                if nc:
                    for _ in range(2):
                        c = x.copy()
                        c[cont] += rng.standard_normal(nc) * cs[cont] * span[cont]
                        cands.append(c)
                        meta.append(("r", -1))
                if not cands:
                    break
                res = evaluate(np.array(cands))
                if res is None:
                    break
                Cx, Cy = res
                spent += len(Cx)
                k = int(np.argmin(Cy))
                if Cy[k] < y - 1e-12 * (1.0 + abs(y)):
                    step = Cx[k] - x
                    x, y = Cx[k].copy(), float(Cy[k])
                    typ, idx = meta[k]
                    if nc:
                        mom[cont] = 0.6 * mom[cont] + step[cont]
                    if typ == "c":
                        cs[idx] = min(cs[idx] * 2.0, 0.5)
                    elif typ == "m":
                        cs[cont] = np.minimum(cs[cont] * 1.2, 0.5)
                    elif typ == "r":
                        cs[cont] = np.minimum(cs[cont] * 1.3, 0.5)
                else:
                    # per-coordinate shrink: coordinates whose both probes failed shrink
                    if nc:
                        for kk in cont:
                            cs[kk] *= 0.6
                        mom *= 0.25
                        if cs[cont].max() < 1e-5:
                            break
                    else:
                        break
            return x, y

        def local_init(n):
            X = np.repeat(best["x"][None, :], n, axis=0)
            scales = np.array([0.01, 0.03, 0.1]) * local_mult["s"]
            sc = scales[rng.integers(0, len(scales), size=n)]
            if nc:
                m = rng.random((n, nc)) < 0.5
                X[:, cont] += m * rng.standard_normal((n, nc)) * sc[:, None] * span[cont]
            for j in disc:
                flip = rng.random(n) < 1.0 / d
                X[flip, j] = rng.integers(0, nv[j], size=int(flip.sum()))
            X[0] = best["x"]
            return repair(X)

        cyc = 0
        lam_glob = lam0
        glob_count = 0
        schedule = (0, 1, 2, 1)
        while used < budget:
            before = used
            stage = schedule[cyc % len(schedule)]
            if stage == 0:
                if glob_count > 0:
                    lam_glob = min(2 * lam_glob, 8 * lam0)
                glob_count += 1
                mu = max(4, lam_glob // 3)
                X0 = lhs(min(lam_glob, budget - used))
                es_run(X0, mu, lam_glob, 0.2, 15)
            elif stage == 1:
                if best["x"] is not None:
                    coord_polish(best["x"], best["y"], 14 * d + 40)
            else:
                if best["x"] is not None:
                    improved = es_run(local_init(min(lam0, budget - used)),
                                      mu0, lam0, 0.05, 6)
                    local_mult["s"] = float(np.clip(
                        local_mult["s"] * (1.5 if improved else 0.7), 0.1, 2.0))
                else:
                    X0 = lhs(min(lam0, budget - used))
                    es_run(X0, mu0, lam0, 0.2, 8)
            cyc += 1
            if used == before:
                break

        best_y = best["y"] if best["x"] is not None else np.inf
        return best_y, best["x"]
